});

use crate::aap::caps::state_read;
use std::collections::HashSet;

struct Node;

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        // Items already recorded in the 'seen' store are dropped. Items repeated
        // within this batch are also dropped after their first occurrence.
        // The id is a parser-computed digest, so it is safe to use as a store key.
        let mut kept_ids: HashSet<String> = HashSet::new();
        let mut out = Vec::with_capacity(items.len());

        for item in items {
            if kept_ids.contains(&item.id) {
                continue;
            }
            if state_read::get(&item.id).is_some() {
                continue;
            }
            kept_ids.insert(item.id.clone());
            out.push(item);
        }

        out
    }
}

export!(Node);
